begin;
create function pro_private.valid_corrective_exercise(e jsonb) returns boolean
language plpgsql stable set search_path='' as $$
declare k text;v jsonb;
begin
 if jsonb_typeof(e) is distinct from 'object' or octet_length(e::text)>30000 or e->>'id' is null or e->>'id' !~ '^[a-z0-9-]{3,80}$'
  or jsonb_typeof(e->'nameFa') is distinct from 'string' or length(btrim(e->>'nameFa')) not between 1 and 300
  or jsonb_typeof(e->'nameEn') is distinct from 'string' or length(btrim(e->>'nameEn')) not between 1 and 300
  or e->>'status' is null or e->>'status' not in('draft','reviewed','published','archived') then return false;end if;
 foreach k in array array['aliases','categories','subgroups','bodyRegions','equipment','muscles','goals','movementTypes','stages','steps','mistakes','precautions','sourceUrls'] loop
  if jsonb_typeof(e->k) is distinct from 'array' or jsonb_array_length(e->k)>50 then return false;end if;
  for v in select value from jsonb_array_elements(e->k) loop if jsonb_typeof(v) is distinct from 'string' or length(v#>>'{}')>2000 then return false;end if;end loop;
 end loop;
 foreach k in array array['difficulty','position','pattern','laterality','start','breathing','reviewer','reviewerQualification','reviewedAt','imageUrl','videoUrl','catalogSource'] loop
  if jsonb_typeof(e->k) is distinct from 'string' or length(e->>k)>2000 then return false;end if;
 end loop;
 foreach k in array array['imageUrl','videoUrl'] loop if e->>k<>'' and e->>k !~ '^https://[^[:space:]]+$' and e->>k !~ '^/training/media/[a-zA-Z0-9_.-]+$' then return false;end if;end loop;
 if e->>'status' in('reviewed','published') then
  foreach k in array array['categories','subgroups','bodyRegions','equipment','muscles','goals','movementTypes','steps','precautions','sourceUrls'] loop
   if jsonb_array_length(e->k)=0 or exists(select 1 from jsonb_array_elements_text(e->k) x where length(btrim(x))=0) then return false;end if;
  end loop;
  foreach k in array array['difficulty','position','start','reviewer','reviewerQualification'] loop if length(btrim(e->>k))=0 then return false;end if;end loop;
  if e->>'reviewedAt' !~ '^\d{4}-\d{2}-\d{2}$' or (e->>'reviewedAt')::date>(now() at time zone 'Asia/Tehran')::date or exists(select 1 from jsonb_array_elements_text(e->'sourceUrls') x where x !~ '^https://[^[:space:]]+$') then return false;end if;
 end if;
 return true;
exception when others then return false;
end $$;
revoke all on function pro_private.valid_corrective_exercise(jsonb) from public,anon,authenticated,service_role;
create table public.pro_corrective_exercises(
 id text primary key check(id ~ '^[a-z0-9-]{3,80}$'),organization_id uuid references public.pro_organizations(id),revision integer not null default 1 check(revision>0),
 content jsonb not null check(pro_private.valid_corrective_exercise(content)),
 created_by uuid references auth.users(id),updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 check(content->>'id'=id),check(organization_id is null or content->>'status' in('draft','archived'))
);
create index pro_corrective_org on public.pro_corrective_exercises(organization_id,id);
alter table public.pro_corrective_exercises enable row level security;
revoke all on public.pro_corrective_exercises from public,anon,authenticated,service_role;
create table pro_private.corrective_exercise_audit(
 id bigint generated always as identity primary key,exercise_id text not null references public.pro_corrective_exercises(id),actor uuid not null references auth.users(id),revision integer not null,before_content jsonb,after_content jsonb not null,created_at timestamptz not null default now());
alter table pro_private.corrective_exercise_audit enable row level security;
revoke all on pro_private.corrective_exercise_audit from public,anon,authenticated,service_role;
create trigger corrective_audit_immutable before update or delete on pro_private.corrective_exercise_audit for each row execute function pro_private.immutable_audit();
create function public.pro_corrective_bank(p_org uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 if not pro_private.has_role(p_org,array['owner','practitioner']) then raise exception 'PRO_ACCESS_DENIED' using errcode='42501';end if;
 return coalesce((select jsonb_agg(content||jsonb_build_object('revision',revision,'ownerOrg',organization_id) order by id) from public.pro_corrective_exercises where organization_id is null or organization_id=p_org),'[]'::jsonb);
end $$;
create function public.admin_corrective_bank() returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 if not public.admin_allowed() then raise exception 'ADMIN_REQUIRED' using errcode='42501';end if;
 return coalesce((select jsonb_agg(content||jsonb_build_object('revision',revision) order by id) from public.pro_corrective_exercises where organization_id is null),'[]'::jsonb);
end $$;
create function public.pro_save_corrective_exercise(p_org uuid,p_exercise jsonb,p_expected integer) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid:=pro_private.verified_actor();prior public.pro_corrective_exercises;next_content jsonb;next_revision integer;
begin
 if actor is null then raise exception 'PRO_AUTH_REQUIRED' using errcode='42501';end if;
 if p_org is null then if not public.admin_allowed() then raise exception 'ADMIN_REQUIRED' using errcode='42501';end if;
 elsif not pro_private.can_write_workspace(p_org) then raise exception 'PRO_ACCESS_DENIED' using errcode='42501';end if;
 if not pro_private.valid_corrective_exercise(p_exercise) or p_expected is null or p_expected<0 then raise exception 'PRO_INVALID_EXERCISE';end if;
 -- Private authors cannot reserve future public catalog IDs.
 if (p_org is not null and p_exercise->>'id' !~ '^custom-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
  or (p_org is null and p_exercise->>'id' !~ '^(ce-[0-9]{3,}|public-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$') then raise exception 'PRO_INVALID_EXERCISE';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_exercise->>'id',54054));
 select * into prior from public.pro_corrective_exercises where id=p_exercise->>'id' for update;
 if found then
  if prior.organization_id is distinct from p_org then raise exception 'PRO_ACCESS_DENIED' using errcode='42501';end if;
  -- Safe lost-response retry uses the same source revision and normalized content.
  if prior.revision=p_expected+1 and (prior.content-'revision'-'ownerOrg')=(p_exercise-'revision'-'ownerOrg') and prior.updated_by=actor then return prior.content||jsonb_build_object('revision',prior.revision,'ownerOrg',p_org);end if;
  if prior.revision<>p_expected then raise exception 'PRO_STALE_REVISION';end if;
 elsif p_expected<>0 then raise exception 'PRO_STALE_REVISION';end if;
 if p_org is not null and p_exercise->>'status' not in('draft','archived') then raise exception 'PRO_REVIEW_REQUIRED';end if;
 next_revision:=p_expected+1;next_content:=(p_exercise-'ownerOrg')||jsonb_build_object('revision',next_revision);
 values(p_exercise->>'id',p_org,next_revision,next_content,actor,actor)
 on conflict(id) do update set revision=excluded.revision,content=excluded.content,updated_by=actor,updated_at=now();
 return next_content||jsonb_build_object('ownerOrg',p_org);
end $$;
revoke all on function public.pro_corrective_bank(uuid),public.admin_corrective_bank(),public.pro_save_corrective_exercise(uuid,jsonb,integer) from public,anon,authenticated,service_role;
grant execute on function public.pro_corrective_bank(uuid),public.admin_corrective_bank(),public.pro_save_corrective_exercise(uuid,jsonb,integer) to authenticated;

alter table public.pro_specialist_profiles add column registered_at timestamptz;
alter table public.pro_specialist_profiles alter column registered_at set default now();
create function public.admin_pro_metrics(p_from date default null,p_to date default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare start_at timestamptz;end_at timestamptz;result jsonb;auto_n bigint;manual_n bigint;auto_t bigint;manual_t bigint;
begin
 if not public.admin_allowed() then raise exception 'ADMIN_REQUIRED' using errcode='42501';end if;
 if (p_from is null)<>(p_to is null) or p_from>p_to then raise exception 'INVALID_DATE_RANGE';end if;
 start_at:=case when p_from is not null then p_from::timestamp at time zone 'Asia/Tehran' end;
 end_at:=case when p_to is not null then (p_to+1)::timestamp at time zone 'Asia/Tehran' end;
 select count(*) into auto_n from public.pro_real_plans where start_at is null or(recorded_at>=start_at and recorded_at<end_at);
 select count(*) into manual_n from public.pro_authored_plans where kind='nutrition' and(start_at is null or(recorded_at>=start_at and recorded_at<end_at));
 select count(*) into auto_t from public.pro_training_approvals where start_at is null or(approved_at>=start_at and approved_at<end_at);
 select count(*) into manual_t from public.pro_authored_plans where kind='training' and(start_at is null or(recorded_at>=start_at and recorded_at<end_at));
 with specialists as (
  select p.user_id,p.profession,coalesce(p.registered_at,a.created_at,(select min(m.created_at) from public.pro_memberships m where m.user_id=p.user_id)) as joined,
   case when p.registered_at is not null then 'profile' when a.created_at is not null then 'application' else 'membership' end as basis
  from public.pro_specialist_profiles p left join public.pro_applications a on a.user_id=p.user_id
 )select jsonb_build_object(
  'specialists',(select count(*) from specialists where start_at is null or(joined>=start_at and joined<end_at)),
  'specialists_by_profession',coalesce((select jsonb_agg(x order by x.profession) from(select profession,count(*) as count from specialists where start_at is null or(joined>=start_at and joined<end_at) group by profession)x),'[]'::jsonb),
  'specialists_date_unknown',(select count(*) from specialists where joined is null),
  'specialists_date_fallback',(select count(*) from specialists where basis<>'profile' and joined is not null and(start_at is null or(joined>=start_at and joined<end_at))),
  'clients',(select count(*) from public.pro_real_cases where start_at is null or(created_at>=start_at and created_at<end_at)),
  'nutrition_total',auto_n+manual_n,'nutrition_automatic',auto_n,'nutrition_authored',manual_n,
  'training_total',auto_t+manual_t,'training_automatic',auto_t,'training_authored',manual_t,
  'body_reports',(select count(*) from public.pro_body_report_jobs where state='complete' and(start_at is null or(created_at>=start_at and created_at<end_at))),
  'from',p_from,'to',p_to,'timezone','Asia/Tehran'
 )into result;
 return result;
end $$;
revoke all on function public.admin_pro_metrics(date,date) from public,anon,authenticated,service_role;
grant execute on function public.admin_pro_metrics(date,date) to authenticated;
notify pgrst,'reload schema';
commit;
